const NEGATIVE_NUMBER_PATTERN = /^-(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$/;

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function buildHelpText(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A       Comma-separated items\n  --b B       Unit name`;
}

function needsValueError(flag) {
  return `argument ${flag}: expected one argument`;
}

function isOptionLikeToken(token) {
  if (token == null || token === '--') {
    return true;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  return !NEGATIVE_NUMBER_PATTERN.test(token);
}

export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParserError';
  }
}

export function parseArguments(argv) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];
  let afterDoubleDash = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (afterDoubleDash) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      afterDoubleDash = true;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return { help: true };
    }

    if (token === '--a' || token === '--b') {
      const key = token.slice(2);
      const value = argv[index + 1];
      if (isOptionLikeToken(value)) {
        throw new ArgumentParserError(needsValueError(token));
      }

      values[key] = value;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (values.a === undefined) {
    missing.push('--a');
  }
  if (values.b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    throw new ArgumentParserError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new ArgumentParserError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

export function parseArgumentsOrExit(
  argv,
  programName,
  {
    stdout = (line) => console.log(line),
    stderr = (line) => console.error(line),
    exit = (code) => process.exit(code),
  } = {},
) {
  let parsed;
  try {
    parsed = parseArguments(argv);
  } catch (error) {
    if (!(error instanceof ArgumentParserError)) {
      throw error;
    }

    stderr(buildUsage(programName));
    stderr(`${programName}: error: ${error.message}`);
    exit(2);
    return null;
  }

  if (parsed.help) {
    stdout(buildHelpText(programName));
    exit(0);
    return null;
  }

  return parsed;
}

