  const rawPath = String(pathValue || "");
  const parts = rawPath.split(/[/\\]+/);
  return parts[parts.length - 1] || "test12.mjs";
}

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}

options:
