function isNegativeNumberToken(token) {
  return /^-\d+(?:\.\d+)?$/.test(token) || /^-\.\d+$/.test(token);
}

function looksLikeOption(token) {
  if (token === undefined || token === "-") {
    return false;
  }

  if (token === "--") {
    return true;
  }

  if (!token.startsWith("-")) {
    return false;
  }

