function isAllUpperCase(value) {
  return value.length > 0 && value === value.toUpperCase() && value !== value.toLowerCase();
}

function isTitleCase(value) {
  if (value.length === 0) {
    return false;
  }

  const first = value[0];
  const rest = value.slice(1);
  return first === first.toUpperCase() && rest === rest.toLowerCase();
}

export function applyWordCase(sourceWord, lowerCaseWord) {
  if (sourceWord === "") {
    return lowerCaseWord;
  }

  if (isAllUpperCase(sourceWord)) {
    return lowerCaseWord.toUpperCase();
  }

  if (isTitleCase(sourceWord)) {
    return lowerCaseWord[0].toUpperCase() + lowerCaseWord.slice(1);
  }

  return lowerCaseWord;
}

